/* =====================================================================
   Retail_Ventas - Script de creación y carga
   Origen: dataset_ventas_retail.xlsx  (Clientes: 200 | Productos: 25 | Ventas: 3000)
   Motor: SQL Server
   ===================================================================== */

-- USE [TuBaseDeDatos];   -- <== descomentar y reemplazar por el nombre de tu base
-- GO

SET NOCOUNT ON;
GO

/* ---------- Limpieza (orden inverso por las FK) ---------- */
IF OBJECT_ID('dbo.ventas','U')    IS NOT NULL DROP TABLE dbo.ventas;
IF OBJECT_ID('dbo.productos','U') IS NOT NULL DROP TABLE dbo.productos;
IF OBJECT_ID('dbo.clientes','U')  IS NOT NULL DROP TABLE dbo.clientes;
GO

/* ---------- Tablas ---------- */
CREATE TABLE dbo.clientes (
    customer_id     VARCHAR(10)    NOT NULL,
    nombre          NVARCHAR(100)  NOT NULL,
    email           NVARCHAR(150)  NOT NULL,
    pais            NVARCHAR(50)   NOT NULL,
    ciudad          NVARCHAR(50)   NOT NULL,
    segmento        NVARCHAR(20)   NOT NULL,
    fecha_registro  DATE           NOT NULL,
    CONSTRAINT PK_clientes PRIMARY KEY (customer_id),
    CONSTRAINT UQ_clientes_email UNIQUE (email)
);
GO

CREATE TABLE dbo.productos (
    product_id       VARCHAR(10)    NOT NULL,
    nombre_producto  NVARCHAR(100)  NOT NULL,
    categoria        NVARCHAR(50)   NOT NULL,
    sub_categoria    NVARCHAR(50)   NOT NULL,
    precio_unitario  DECIMAL(10,2)  NOT NULL,
    CONSTRAINT PK_productos PRIMARY KEY (product_id),
    CONSTRAINT CK_productos_precio CHECK (precio_unitario > 0)
);
GO

CREATE TABLE dbo.ventas (
    transaction_id  VARCHAR(12)    NOT NULL,
    customer_id     VARCHAR(10)    NOT NULL,
    product_id      VARCHAR(10)    NOT NULL,
    fecha_compra    DATE           NOT NULL,
    cantidad        INT            NOT NULL,
    monto_total     DECIMAL(12,2)  NOT NULL,
    medio_pago      NVARCHAR(30)   NOT NULL,
    CONSTRAINT PK_ventas PRIMARY KEY (transaction_id),
    CONSTRAINT FK_ventas_clientes  FOREIGN KEY (customer_id) REFERENCES dbo.clientes(customer_id),
    CONSTRAINT FK_ventas_productos FOREIGN KEY (product_id)  REFERENCES dbo.productos(product_id),
    CONSTRAINT CK_ventas_cantidad CHECK (cantidad > 0),
    CONSTRAINT CK_ventas_monto    CHECK (monto_total >= 0)
);
GO

CREATE INDEX IX_ventas_customer_id  ON dbo.ventas(customer_id);
CREATE INDEX IX_ventas_product_id   ON dbo.ventas(product_id);
CREATE INDEX IX_ventas_fecha_compra ON dbo.ventas(fecha_compra);
GO

